// -er conjugation suffixes -> tense (ordered longest-first; port of _ER_RULES).
const _ER_RULES = [
  ["ées$", "participle f. pl"], ["és$", "participle m. pl"],
  ["ée$", "participle f. sg"], ["é$", "past participle"],
  ["eront$", "futur 3pl"], ["erons$", "futur 1pl"],
  ["erez$", "futur 2pl"], ["eras$", "futur 2sg"],
  ["era$", "futur 3sg"], ["erai$", "futur 1sg"],
  ["eraient$", "conditionnel 3pl"], ["eriez$", "conditionnel 2pl"],
  ["erions$", "conditionnel 1pl"], ["erait$", "conditionnel 3sg"],
  ["erais$", "conditionnel 1/2sg"],
  ["aient$", "imparfait 3pl"], ["iez$", "imparfait 2pl"],
  ["ions$", "imparfait 1pl"], ["ait$", "imparfait 3sg"],
  ["ais$", "imparfait 1/2sg"],
  ["èrent$", "passé simple 3pl"], ["âtes$", "passé simple 2pl"],
  ["âmes$", "passé simple 1pl"], ["ai$", "passé simple 1sg"],
  ["à$", "passé simple 3sg"],
  ["â$", "passé simple 3sg"],
  ["ons$", "présent 1pl"], ["ez$", "présent 2pl"],
  ["ent$", "présent 3pl"],
  ["a$", "passé simple 3sg"],
  ["es$", "présent 2sg"], ["e$", "présent 1/3sg"],
];

// -ir rules (port of _IR_RULES).
const _IR_RULES = [
  ["issant$", "participle"], ["ie?nt$", "présent 3pl"],
  ["issent$", "présent 3pl"],
  ["issaient$", "imparfait 3pl"], ["issait$", "imparfait 3sg"], ["issais$", "imparfait 1/2sg"],
  ["iraient$", "conditionnel 3pl"], ["iriez$", "conditionnel 2pl"],
  ["irions$", "conditionnel 1pl"], ["irait$", "conditionnel 3sg"],
  ["irais$", "conditionnel 1/2sg"],
  ["iront$", "futur 3pl"], ["irez$", "futur 2pl"], ["irons$", "futur 1pl"],
  ["ira$", "futur 3sg"], ["irai$", "futur 1sg"], ["iras$", "futur 2sg"],
  ["issons$", "présent 1pl"], ["issez$", "présent 2pl"],
  ["isse$", "subjonctif 1/3sg"],
  ["irent$", "passé simple 3pl"],
  ["it$", "présent/ passé simple 3sg"],
  ["i$", "participe passé"],
];

function _stripElisions(word) {
  return word.replace(/[’']/g, "");
}

const _IRR_ER_VERBS = new Set(["aller", "envoyer", "renvoyer"]);

function verbInfinitive(word) {
  const f = word.toLowerCase().replace(/[’‘]/g, "'");
  if (_VERB_IRREGULAR[f]) {
    // memory-form verbs (take, va, fut, soit...) carry no derivable ending, so
    // the tuple is [inf, tense, "", flags] with the irregular marker.
    const e = _VERB_IRREGULAR[f];
    return [[e[0], e[1], "", { irregular: true }]];
  }
  const w = _stripElisions(f);
  const out = [];
  // -er verbs (longest suffix first; try every matching suffix and let the
  // dictionary pick the right stem: "prions" must fall through "ions$" ->
  // "prer" (no hit) to "ons$" -> "prier")
  for (const [re, tense] of _ER_RULES) {
    const m = new RegExp(re).exec(w);
    if (m) {
      const base = w.slice(0, m.index);
      if (!base) continue;
      // orthographic -ger: "mangea" -> base "mange" -> real stem "mang",
      // infinitive "manger", but the word spells the stem "mange-", so the
      // ending shown on the gloss is the part after it ("-a", "-ait").
      if (/ge$/.test(base)) {
        out.push([base.slice(0, -1) + "er", tense, w.slice(base.length)]);
        continue;
      }
      // orthographic -cer: "lança" -> canonical stem "lanc", infinitive
      // "lancer" (the cedille is just the spelling of "c" before -a).
      out.push([base.replace(/ç$/, "c") + "er", tense, w.slice(base.length)]);
    }
  }
  // third-group guesses for forms the -er rule shapes from wrong stems
  // (rendait -> rendre, atendait -> attendre, sortent -> sortir, ...). The
  // suffix still tells us the tense (rendait is imparfait even for rendre),
  // so carry the matched -er rule's label instead of the generic "3e groupe".
  const erBase = out.length ? out[0][0].slice(0, -2) : null;
  const erEnding = out.length ? out[0][2] || "" : "";
  if (erBase && erBase.length > 3) {
    out.push([erBase + "ir", out[0][1], erEnding]);
    out.push([erBase + "re", out[0][1], erEnding]);
  }
  // present participles in -ant (donnant -> donner, contenant -> contenir,
  // servant -> servir): the stem takes -er or -ir depending on the group.
  if (/ant$/.test(w)) {
    const base = w.slice(0, -3);
    if (base.length > 2) {
      out.push([base + "er", "participe présent", "ant"]);
      out.push([base + "ir", "participe présent", "ant"]);
    }
  }
  // participles of 3rd group verbs whose fem./pl. forms don't fit the -er/-ir
  // patterns («partie» -> partir, «souvenu» -> se souvenir, «guérie» -> guérir,
  // «revenues» -> revenir). Guesses; only real dictionary stems survive lookup.
  const _P3 = [
    ["ies$", "participle f. pl"], ["ue$", "participle f. sg"],
    ["ues$", "participle f. pl"], ["us$", "participle m. pl"],
    ["ie$", "participle f. sg"], ["is$", "participle m. pl"],
    ["u$", "participe passé"]
  ];
  for (const [re, tense] of _P3) {
    // Los pronombres «nous»/«vous» no derivan participios aunque terminen en
    // «ous»/«us» («nous» -> no+ir = noir, «vous» -> vo+ir = voir); el sufijo
    // «us$» coincide de forma casual y falsea compuestos como «c'est vous».
    if (w === "nous" || w === "vous") continue;
    const m = new RegExp(re).exec(w);
    if (m) {
      const base = w.slice(0, m.index);
      if (base.length >= 2) {
        out.push([base + "ir", tense, m[0]]);
        out.push([base + "re", tense, m[0]]);
      }
    }
  }
  // participios en -çu/-çue/-çus/-çues de la familia «-cevoir» (apercevoir,
  // recevoir, percevoir, concevoir, décevoir): la base queda cerrada en -e-.
  for (const [re, tense] of [["çues$", "participe passé f. pl"], ["çue$", "participe passé f."], ["çus$", "participe passé pl"], ["çu$", "participe passé"]]) {
    const m = new RegExp(re).exec(w);
    if (m && m.index >= 1) out.push([w.slice(0, m.index) + "cevoir", tense, m[0]]);
  }
  // -ir verbs
  for (const [re, tense] of _IR_RULES) {
    const m = new RegExp(re).exec(w);
    if (m) {
      const base = w.slice(0, m.index);
      if (base) out.push([base + "ir", tense, m[0]]);
    }
  }
  // 3rd-group -ire verbs (lire, conduire, cuire, traduire): the present stem
  // ends in -is- (lisez, conduisons, cuisent) without the -iss- infix of the
  // 2nd group; the "ire" infinitive is reached through those stems.
  for (const [suffix, tense, cut] of [["isons", "présent 1pl", 5], ["isez", "présent 2pl", 4], ["isent", "présent 3pl", 5]]) {
    if (w.endsWith(suffix)) {
      const base = w.slice(0, -cut);
      if (base.length >= 1) out.push([base + "ire", tense, suffix]);
    }
  }
  // -re verbs: past participles in -u (attendu -> attendre, rendu -> rendre, ...)
  if (/u$/.test(w) && w.length > 3) {
    out.push([w.slice(0, -1) + "re", "participe passé", "u"]);
  }
  return out;
}

// ---- friendly explanations of tense / form labels -------------------------
const _TENSE_FR = {
  "présent": "presente (algo que ocurre ahora)",
  "imparfait": "pasado incompleto (describía hábitos o acciones en curso)",
  "passé simple": "pasado simple (una acción concreta y terminada)",
  "passé simple (archaïque)": "pasado simple (una forma antigua que a veces aparece en la Biblia)",
  "futur": "futuro (ocurrirá)",
  "futur inversion": "futuro (con el verbo invertido, típico de preguntas)",
  "conditionnel": "condicional (lo que ocurriría si hiciera falta)",
  "conditionnel clitique": "condicional (con un pronombre unido al verbo)",
  "subjonctif": "subjuntivo (deseo, duda o emoción)",
  "impératif": "imperativo (una orden)",
  "passé composé": "pretérito perfecto compuesto (una acción ya terminada: «ha hablado»)",
  "plus-que-parfait": "pretérito pluscuamperfecto (una acción que ya había acabado: «había hablado»)",
  "passé antérieur": "pasado anterior (una acción que terminó justo antes de otra: «hubo hablado»)",
  "futur antérieur": "futuro compuesto (una acción que ya habrá terminado: «habrá hablado»)",
  "conditionnel passé": "condicional compuesto (lo que habría ocurrido: «habría hablado»)",
  "subjonctif passé": "subjuntivo compuesto (deseo o duda sobre algo ya hecho: «haya hablado»)",
  "verbe 3e groupe ?": "un verbo del 3.er grupo (irregular)"
};

const _PARTICIPLE_FR = {
  "past participle": "participio pasado («-ado / -ido»)",
  "participe": "participio",
  "participle": "participio",
  "participe passé": "participio pasado («-ado / -ido»)",
  "participe passé pl": "participio pasado, plural («-ados / -adas»)",
  "participe passé f.": "participio pasado, femenino singular («-ada»)",
  "participe passé f. pl": "participio pasado, femenino plural («-adas»)",
  "participe pl": "participio, plural («-ados / -adas»)",
  "participle f. sg": "participio pasado, femenino singular («-ada»)",
  "participle m. pl": "participio pasado, masculino plural («-ados»)",
  "participle f. pl": "participio pasado, femenino plural («-adas»)",
  "participe présent": "participio presente («-ando / -iendo»)",
  "participe présent f.": "participio presente, femenino («-ando / -iendo»)",
  "participle présent": "participio presente («-ando / -iendo»)"
};

const _PERSON_FR = {
  "1sg": "1.ª persona del singular (yo)",
  "2sg": "2.ª persona del singular (tú)",
  "3sg": "3.ª persona del singular (él / ella)",
  "1pl": "1.ª persona del plural (nosotros / nosotras)",
  "2pl": "2.ª persona del plural (ustedes)",
  "3pl": "3.ª persona del plural (ellos / ellas)",
  "1/2sg": "1.ª o 2.ª persona del singular (yo / tú)",
  "1/3sg": "1.ª o 3.ª persona del singular (yo / él / ella)",
  "1sg/2sg": "1.ª o 2.ª persona del singular (yo / tú)",
  "1sg/3sg": "1.ª o 3.ª persona del singular (yo / él / ella)",
  "3sg/1sg": "1.ª o 3.ª persona del singular (yo / él / ella)",
  "2sg/1sg": "1.ª o 2.ª persona del singular (yo / tú)"
};

function friendlyTense(label) {
  if (!label) return "";
  label = String(label).trim();
  const persons = [];
  label = label.replace(/\b(1\s*\/\s*3sg|1\s*\/\s*2sg|1sg\s*\/\s*2sg|1sg\s*\/\s*3sg|3sg\s*\/\s*1sg|2sg\s*\/\s*1sg|1sg|2sg|3sg|1pl|2pl|3pl)\b/g, (tok) => {
    const key = tok.replace(/\s+/g, "");
    persons.push(_PERSON_FR[key] || tok);
    return "";
  });
  label = label.replace(/\s+/g, " ").trim().replace(/^[,;\·\/\s]+|[,;\·\/\s]+$/g, "");
  const names = [];
  for (const part of label.split("/")) {
    const p = part.trim();
    if (!p) continue;
    const low = p.toLowerCase();
    if (_PARTICIPLE_FR[low]) names.push(_PARTICIPLE_FR[low]);
    else if (_TENSE_FR[low]) names.push(_TENSE_FR[low]);
    else names.push(p);
  }
  let text = names.length ? names.join(" o ") : label;
  if (persons.length) text = text ? `${text} · ${[...new Set(persons)].join(" o ")}` : [...new Set(persons)].join(" o ");
  return text;
}

function friendlyForm(label) {
  if (!label) return "";
  label = String(label).trim();
  let m = label.match(/^plural de «(.+)»$/);
  if (m) {
    return `es el plural de «${m[1]}» — se refiere a varias personas o cosas`;
  }
  m = label.match(/^«(.+)-…»\s*\(forma compuesta\)$/);
  if (m) {
    return `es una forma compuesta: el verbo «${m[1]}» con un pronombre unido (p. ej. «${m[1]}-la» = «${m[1]}» + «la»)`;
  }
  return label;
}

